type Props = {
  label: string;
  value: string;
  onChange: (v: string) => void;
  placeholder?: string;
  error?: string;
};

export default function {{component_name}}({ label, value, onChange, placeholder, error }: Props) {
  return (
    <label className="block">
      <span className="text-sm text-gray-700">{label}</span>
      <input
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        className={`mt-1 w-full px-3 py-2 border rounded ${error ? 'border-red-500' : 'border-gray-300'}`}
      />
      {error && <span className="text-sm text-red-500">{error}</span>}
    </label>
  );
}
